'use strict';
const app=document.querySelector('#app'),nav=document.querySelector('#nav');
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
let users=read('subway-demo-users',[]),session=read('subway-demo-session',null),entry=10;
const money=n=>Number(n).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const current=()=>users.find(u=>u.email===session);
const persist=()=>{const ref=sessionStorage.getItem('subway-demo-referrer'),candidate=users.at(-1);if(ref&&candidate&&!candidate.referredBy&&candidate.id!==ref){candidate.referredBy=ref;sessionStorage.removeItem('subway-demo-referrer')}localStorage.setItem('subway-demo-users',JSON.stringify(users))};
async function hash(password,salt){const bytes=new TextEncoder().encode(salt+password);return [...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(b=>b.toString(16).padStart(2,'0')).join('')}
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.style.display='none',3200)}
function renderView(){const user=current();const view=location.hash.slice(1)||'login';document.querySelector('#account').hidden=!user;nav.hidden=!user;if(!user){renderAuth(view==='cadastro');return}document.querySelectorAll('[data-balance]').forEach(el=>el.textContent=money(user.balance));document.querySelector('.avatar').textContent=user.name.charAt(0).toUpperCase();nav.querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(['login','cadastro'].includes(view)){location.hash='jogar';return}if(view==='depositar')deposit();else if(view==='sacar')withdraw();else if(view==='indicar')referral();else if(view==='perfil')profile();else home()}
function render(){renderView();if(window.lucide)lucide.createIcons({attrs:{"aria-hidden":"true","stroke-width":1.8}})}
function renderAuth(register){app.innerHTML=`<section class="auth auth-mobile"><div class="auth-art"><img class="auth-logo" src="jogar/assets/preload/splash.png" alt="Subway Surfers"><div class="auth-game-icon"><img src="jogar/assets/images/app-icon-144.png" alt=""></div></div><div class="auth-tabs" role="tablist"><a href="#login" class="${register?'':'active'}">Entrar</a><a href="#cadastro" class="${register?'active':''}">Criar conta</a></div><div class="auth-title"><span class="eyebrow">SUBWAY PAY</span><h1>${register?'Crie sua conta':'Bem-vindo de volta'}</h1><p>${register?'Preencha seus dados para começar a jogar.':'Entre para continuar sua corrida.'}</p></div><form class="card auth-card" id="auth-form">${register?'<label for="name">Nome completo</label><div class="auth-field"><i data-lucide="user-round"></i><input id="name" name="name" autocomplete="name" required minlength="2" maxlength="60" placeholder="Digite seu nome"></div>':''}<label for="email">E-mail</label><div class="auth-field"><i data-lucide="mail"></i><input id="email" name="email" type="email" autocomplete="email" required maxlength="120" placeholder="voce@exemplo.com"></div><label for="password">Senha</label><div class="auth-field"><i data-lucide="lock-keyhole"></i><input id="password" name="password" type="password" autocomplete="${register?'new-password':'current-password'}" required minlength="6" placeholder="Pelo menos 6 caracteres"><button type="button" class="password-toggle" data-target="password" aria-label="Mostrar senha"><i data-lucide="eye"></i></button></div>${register?'<label for="confirm">Confirmar senha</label><div class="auth-field"><i data-lucide="shield-check"></i><input id="confirm" name="confirm" type="password" autocomplete="new-password" required minlength="6" placeholder="Repita sua senha"><button type="button" class="password-toggle" data-target="confirm" aria-label="Mostrar senha"><i data-lucide="eye"></i></button></div>':''}<p class="error" id="auth-error" role="alert"></p><button class="primary auth-submit" type="submit"><i data-lucide="${register?'user-plus':'log-in'}"></i>${register?'Criar minha conta':'Entrar na conta'}</button></form><p class="auth-privacy"><i data-lucide="lock"></i> Seus dados de demonstração ficam somente neste navegador.</p></section>`;document.querySelectorAll('.password-toggle').forEach(button=>button.onclick=()=>{const input=document.querySelector('#'+button.dataset.target),show=input.type==='password';input.type=show?'text':'password';button.setAttribute('aria-label',show?'Ocultar senha':'Mostrar senha');button.innerHTML=`<i data-lucide="${show?'eye-off':'eye'}"></i>`;lucide.createIcons({attrs:{"aria-hidden":"true"}})});document.querySelector('#auth-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),email=f.get('email').trim().toLowerCase(),password=f.get('password'),error=document.querySelector('#auth-error'),button=e.target.querySelector('.auth-submit');error.textContent='';button.disabled=true;try{if(register){if(password!==f.get('confirm'))throw Error('As senhas precisam ser iguais.');if(users.some(u=>u.email===email))throw Error('Este e-mail já está cadastrado neste navegador.');const name=f.get('name').trim();if(name.length<2)throw Error('Informe seu nome.');const salt=crypto.randomUUID();users.push({email,name,salt,passwordHash:await hash(password,salt),balance:0,id:crypto.randomUUID()});persist()}else{const u=users.find(u=>u.email===email);if(!u||u.passwordHash!==await hash(password,u.salt))throw Error('E-mail ou senha incorretos. Cadastre uma conta neste navegador.')}session=email;localStorage.setItem('subway-demo-session',JSON.stringify(session));location.hash='jogar';render()}catch(err){error.textContent=err.message}finally{button.disabled=false}}}
function home(){const u=current();app.innerHTML=`<section class="layout"><div class="balance"><span class="eyebrow">Seu saldo disponível · demo</span><h1>${money(u.balance)}</h1><div class="actions"><button class="pill gold" data-view="depositar"><i data-lucide="arrow-down-left"></i> Depositar</button><button class="pill" data-view="sacar"><i data-lucide="arrow-up-right"></i> Sacar</button><button class="pill" data-view="indicar"><i data-lucide="users"></i> Indicar</button></div></div><section class="card"><div class="game-cover"><div class="game-cover-copy"><span class="cover-label">SUA PRÓXIMA CORRIDA</span><h2>Correr nos trilhos</h2><p>Colete moedas. Cada 100 moedas soma 1x à entrada demo.</p></div><img src="jogar/assets/preload/splash.png" alt="Subway Surfers"></div><div class="badges"><span class="badge"><i data-lucide="target"></i> Meta = 4x</span><span class="badge blue"><i data-lucide="zap"></i> Modo demonstração</span></div><label for="entry">VALOR DE ENTRADA</label><div class="quick"><button data-amount="10">R$10</button><button data-amount="30">R$30</button><button data-amount="60">R$60</button></div><div class="amount"><span>R$</span><input id="entry" aria-label="Valor de entrada" type="number" min="10" max="400" step="1" value="${entry}" inputmode="decimal"></div><div class="stats"><div><span>Meta de ganho</span><strong id="target">${money(entry*4)}</strong></div><div><span>Mín. entrada</span><strong>R$ 10,00</strong></div><div><span>Máx. entrada</span><strong>R$ 400,00</strong></div></div><div class="notice" id="entry-status"></div><button class="primary" id="start-game"></button></section><p class="demo">Saldo e valores são fictícios. Sem apostas ou prêmios reais.</p></section>`;const input=document.querySelector('#entry');input.oninput=()=>{entry=Number(input.value);document.querySelector('#target').textContent=money(entry*4);updateEntry()};document.querySelectorAll('[data-amount]').forEach(b=>b.onclick=()=>{entry=Number(b.dataset.amount);input.value=entry;input.oninput()});document.querySelector('#start-game').onclick=()=>{if(!Number.isFinite(entry)||entry<10||entry>400){toast('Informe um valor entre R$10 e R$400.');return}const active=read('subway-demo-round',null);if(active?.status==='active'&&active.email===u.email){toast('Retomando sua corrida.');location.href='jogar/';return}if(u.balance<entry){location.hash='depositar';return}u.balance=Math.round((u.balance-entry)*100)/100;persist();localStorage.setItem('subway-demo-round',JSON.stringify({id:crypto.randomUUID(),email:u.email,entry,status:'active'}));localStorage.setItem('realBetPage','true');location.href='jogar/'};updateEntry()}
function updateEntry(){const u=current(),valid=Number.isFinite(entry)&&entry>=10&&entry<=400,status=document.querySelector('#entry-status'),button=document.querySelector('#start-game');status.textContent=!valid?'Informe uma entrada entre R$10 e R$400.':u.balance<entry?'Saldo demo insuficiente para jogar':'Entrada pronta. Sua entrada demo será debitada ao iniciar.';button.innerHTML=!valid?'<i data-lucide="sliders-horizontal"></i> Ajustar valor':u.balance<entry?'<i data-lucide="wallet"></i> Adicionar saldo demo':'<i data-lucide="play"></i> Jogar demonstração';if(window.lucide)lucide.createIcons({attrs:{"aria-hidden":"true"}})}
function deposit(){const multiplier=value=>value===200?5:value>=100?2:1;app.innerHTML=`<section class="layout screen deposit-screen"><div class="deposit-title"><div><span class="eyebrow">CARTEIRA DEMO</span><h1>Adicionar saldo</h1></div><span class="deposit-safe"><i data-lucide="shield-check"></i> Crédito instantâneo</span></div><div class="deposit-promo"><div><span class="promo-label">MELHOR OFERTA</span><h2>R$ 200 vira R$ 1.000</h2><p>Escolha R$ 200 e receba cinco vezes o valor em créditos para jogar.</p></div><strong>5x</strong></div><div class="card deposit-card"><div class="deposit-balance"><span>Saldo disponível</span><strong>${money(current().balance)}</strong></div><form id="deposit-form"><label class="deposit-label">Escolha o valor</label><div class="deposit-options"><button type="button" data-deposit="20"><span>R$ 20</span><small>Valor inicial</small></button><button type="button" data-deposit="30"><span>R$ 30</span><small>Sem bônus</small></button><button type="button" data-deposit="75"><span>R$ 75</span><small>Sem bônus</small></button><button type="button" data-deposit="100" class="selected bonus"><span>R$ 100</span><small>Receba R$ 200</small><b>2x</b></button><button type="button" data-deposit="150" class="bonus"><span>R$ 150</span><small>Receba R$ 300</small><b>2x</b></button><button type="button" data-deposit="200" class="bonus featured"><span>R$ 200</span><small>Receba R$ 1.000</small><b>5x</b></button></div><label for="deposit-value">Outro valor entre R$ 20 e R$ 200</label><div class="amount deposit-amount"><span>R$</span><input id="deposit-value" name="value" type="number" inputmode="decimal" value="100" min="20" max="200" step="1" required></div><div class="deposit-summary"><div><span>Valor escolhido</span><strong id="deposit-base">R$ 100,00</strong></div><div><span>Bônus aplicado</span><strong id="deposit-bonus">+ R$ 100,00</strong></div><div class="deposit-total"><span>Você recebe</span><strong id="deposit-credit">R$ 200,00</strong></div></div><p class="deposit-rule" id="deposit-rule"><i data-lucide="sparkles"></i> Bônus 2x aplicado neste valor.</p><p class="error" id="deposit-error" role="alert"></p><button class="primary deposit-submit"><i data-lucide="wallet-cards"></i><span>Adicionar <strong id="deposit-button-value">R$ 200,00</strong></span></button></form><p class="deposit-disclaimer">Créditos fictícios para demonstração. Nenhuma cobrança ou PIX será gerado.</p></div></section>`;const input=document.querySelector('#deposit-value'),error=document.querySelector('#deposit-error');function update(){const value=Number(input.value),valid=Number.isFinite(value)&&value>=20&&value<=200,m=valid?multiplier(value):1,credit=valid?value*m:0,bonus=valid?credit-value:0;document.querySelector('#deposit-base').textContent=valid?money(value):'—';document.querySelector('#deposit-bonus').textContent=valid?'+ '+money(bonus):'—';document.querySelector('#deposit-credit').textContent=valid?money(credit):'—';document.querySelector('#deposit-button-value').textContent=valid?money(credit):'saldo';const rule=document.querySelector('#deposit-rule');rule.innerHTML=m===5?'<i data-lucide="sparkles"></i> Oferta especial 5x aplicada.':m===2?'<i data-lucide="sparkles"></i> Bônus 2x aplicado neste valor.':'<i data-lucide="circle-check"></i> Valor creditado sem bônus.';error.textContent=valid?'':'Informe um valor entre R$ 20 e R$ 200.';document.querySelectorAll('[data-deposit]').forEach(b=>b.classList.toggle('selected',Number(b.dataset.deposit)===value));if(window.lucide)lucide.createIcons({attrs:{"aria-hidden":"true"}})}document.querySelectorAll('[data-deposit]').forEach(b=>b.onclick=()=>{input.value=b.dataset.deposit;update()});input.oninput=update;document.querySelector('#deposit-form').onsubmit=e=>{e.preventDefault();const value=Number(input.value);if(!Number.isFinite(value)||value<20||value>200){error.textContent='Informe um valor entre R$ 20 e R$ 200.';return}const credit=value*multiplier(value);current().balance=Math.round((current().balance+credit)*100)/100;persist();location.hash='jogar';toast(money(credit)+' em créditos adicionados.')}}
function withdraw(){const u=current(),history=read('subway-demo-withdrawals',[]).filter(item=>item.email===u.email).slice(-3).reverse();app.innerHTML=`<section class="layout screen withdraw-screen"><div class="withdraw-title"><span class="eyebrow">CARTEIRA DEMO</span><h1>Sacar saldo</h1><p>Informe o valor e a chave PIX para criar uma solicitação de demonstração.</p></div><div class="withdraw-balance"><div><span>Saldo disponível</span><strong>${money(u.balance)}</strong><small>Valor mínimo para solicitar: R$ 20,00</small></div><i data-lucide="landmark"></i></div><div class="card withdraw-card"><form id="withdraw-form"><label>Escolha o valor</label><div class="withdraw-options"><button type="button" data-withdraw="20" ${u.balance<20?'disabled':''}>R$ 20</button><button type="button" data-withdraw="50" ${u.balance<50?'disabled':''}>R$ 50</button><button type="button" data-withdraw="100" ${u.balance<100?'disabled':''}>R$ 100</button><button type="button" data-withdraw="all" ${u.balance<20?'disabled':''}>Todo saldo</button></div><label for="withdraw-value">Valor do saque</label><div class="amount withdraw-amount"><span>R$</span><input id="withdraw-value" name="value" type="number" inputmode="decimal" min="20" max="${u.balance}" step="1" value="${u.balance>=20?Math.min(20,u.balance):''}" required></div><div class="pix-fields"><div><label for="pix-type">Tipo de chave</label><select id="pix-type" name="pixType"><option value="cpf">CPF</option><option value="email">E-mail</option><option value="phone">Celular</option><option value="random">Chave aleatória</option></select></div><div><label for="pix-key">Chave PIX</label><input id="pix-key" name="pixKey" autocomplete="off" placeholder="Digite sua chave" required maxlength="120"></div></div><div class="withdraw-summary"><span>Valor da solicitação</span><strong id="withdraw-total">${u.balance>=20?money(Math.min(20,u.balance)):'—'}</strong></div><p class="error" id="withdraw-error" role="alert"></p><button class="primary withdraw-submit" ${u.balance<20?'disabled':''}><i data-lucide="arrow-up-right"></i> Solicitar saque demo</button></form><p class="withdraw-disclaimer">Fluxo apenas demonstrativo. Nenhuma transferência real será realizada.</p></div>${history.length?`<section class="withdraw-history"><h2>Solicitações recentes</h2>${history.map(item=>`<div><span><i data-lucide="clock-3"></i>${new Date(item.createdAt).toLocaleDateString('pt-BR')}</span><strong>${money(item.value)}</strong><small>Em análise · demonstração</small></div>`).join('')}</section>`:''}</section>`;const input=document.querySelector('#withdraw-value'),error=document.querySelector('#withdraw-error'),total=document.querySelector('#withdraw-total');function update(){const value=Number(input.value),valid=Number.isFinite(value)&&value>=20&&value<=u.balance;total.textContent=valid?money(value):'—';error.textContent=!Number.isFinite(value)||value<20?'O saque mínimo é R$ 20,00.':value>u.balance?'O valor ultrapassa seu saldo disponível.':'';document.querySelectorAll('[data-withdraw]').forEach(button=>button.classList.toggle('selected',button.dataset.withdraw==='all'?value===u.balance:Number(button.dataset.withdraw)===value))}document.querySelectorAll('[data-withdraw]').forEach(button=>button.onclick=()=>{input.value=button.dataset.withdraw==='all'?u.balance:button.dataset.withdraw;update()});input.oninput=update;document.querySelector('#withdraw-form').onsubmit=e=>{e.preventDefault();const value=Number(input.value),pixKey=e.target.elements.pixKey.value.trim();if(!Number.isFinite(value)||value<20){error.textContent='O saque mínimo é R$ 20,00.';return}if(value>u.balance){error.textContent='O valor ultrapassa seu saldo disponível.';return}if(pixKey.length<4){error.textContent='Informe uma chave PIX válida para a demonstração.';return}u.balance=Math.round((u.balance-value)*100)/100;const requests=read('subway-demo-withdrawals',[]);requests.push({id:crypto.randomUUID(),email:u.email,value,pixType:e.target.elements.pixType.value,pixKey,createdAt:new Date().toISOString(),status:'pending-demo'});localStorage.setItem('subway-demo-withdrawals',JSON.stringify(requests));persist();withdraw();if(window.lucide)lucide.createIcons({attrs:{"aria-hidden":"true"}});toast('Solicitação demo de '+money(value)+' criada.')}}
function referral(){const u=current(),link=location.origin+'/#cadastro?ref='+u.id,code=u.id.replaceAll('-','').slice(0,8).toUpperCase(),shareKey='subway-demo-referral-shares:'+u.id,shares=Number(read(shareKey,0))||0,invited=users.filter(user=>user.referredBy===u.id);app.innerHTML=`<section class="layout screen referral-screen"><div class="referral-hero"><div><span class="eyebrow">PROGRAMA DE CONVITES</span><h1>Convide seus amigos</h1><p>Compartilhe seu link pessoal para apresentar o jogo.</p></div><i data-lucide="users-round"></i></div><div class="referral-stats"><div><span>Compartilhamentos</span><strong id="share-count">${shares}</strong></div><div><span>Cadastros locais</span><strong>${invited.length}</strong></div><div><span>Seu código</span><strong>${code}</strong></div></div><div class="card referral-card"><label for="referral">Seu link de indicação</label><div class="referral-link"><input id="referral" readonly value="${escape(link)}"><button id="copy-link" aria-label="Copiar link"><i data-lucide="copy"></i></button></div><div class="referral-actions"><button class="primary" id="share-whatsapp"><i data-lucide="message-circle"></i> Compartilhar no WhatsApp</button><button class="secondary" id="share-native"><i data-lucide="share-2"></i> Outras opções</button></div><p class="referral-note">Área de demonstração. Convites não geram comissões ou pagamentos reais.</p></div><section class="referral-steps"><h2>Como funciona</h2><div><span>1</span><p><strong>Compartilhe</strong>Envie seu link para um amigo.</p></div><div><span>2</span><p><strong>Cadastro</strong>Ele abre o link e cria uma conta.</p></div><div><span>3</span><p><strong>Acompanhe</strong>Veja seus indicadores nesta tela.</p></div></section>${invited.length?`<section class="referral-list"><h2>Cadastros recentes</h2>${invited.slice(-3).reverse().map(user=>`<div><span>${escape(user.name.charAt(0).toUpperCase())}</span><p><strong>${escape(user.name)}</strong><small>Conta criada neste navegador</small></p><i data-lucide="circle-check"></i></div>`).join('')}</section>`:`<div class="referral-empty"><i data-lucide="user-plus"></i><strong>Nenhum cadastro ainda</strong><span>Seus convites aparecerão aqui.</span></div>`}</section>`;function record(){const total=(Number(read(shareKey,0))||0)+1;localStorage.setItem(shareKey,JSON.stringify(total));document.querySelector('#share-count').textContent=total}document.querySelector('#copy-link').onclick=async()=>{try{await navigator.clipboard.writeText(link);record();toast('Link de indicação copiado.')}catch{document.querySelector('#referral').select();toast('Selecione e copie o link.')}};document.querySelector('#share-whatsapp').onclick=()=>{record();window.open('https://wa.me/?text='+encodeURIComponent('Venha conhecer o Subway Pay: '+link),'_blank','noopener')};document.querySelector('#share-native').onclick=async()=>{if(navigator.share){try{await navigator.share({title:'Subway Pay',text:'Venha conhecer o jogo',url:link});record()}catch{}}else{try{await navigator.clipboard.writeText(link);record();toast('Link copiado para compartilhar.')}catch{toast('Use o botão de copiar link.')}}}}
function profile(){const u=current();app.innerHTML=`<section class="layout screen"><h1>Meu perfil</h1><div class="card"><h2>${escape(u.name)}</h2><div class="profile-row"><small>E-mail</small>${escape(u.email)}</div><div class="profile-row"><small>Saldo de demonstração</small>${money(u.balance)}</div><p class="muted">Sua conta existe somente neste navegador.</p><button class="secondary" id="logout"><i data-lucide="log-out"></i> Sair da conta</button></div></section>`;document.querySelector('#logout').onclick=()=>{session=null;localStorage.removeItem('subway-demo-session');location.hash='login';render()}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(b)location.hash=b.dataset.view});window.addEventListener('hashchange',render);if(location.hash.startsWith('#cadastro?')){const ref=new URLSearchParams(location.hash.split('?')[1]).get('ref');if(ref)sessionStorage.setItem('subway-demo-referrer',ref);location.hash='cadastro'}render();
